<style>.manual-order-entry,.manual-order-entry .card,.manual-order-entry .card-body{min-width:0}.manual-order-entry strong{overflow-wrap:anywhere}.manual-order-entry select{max-width:100%;min-width:0}.manual-order-line{display:grid;grid-template-columns:42px minmax(0,1fr) 65px 36px;align-items:center;gap:8px!important}.manual-order-line input{width:100%!important;padding:8px}.manual-order-line button{padding:8px}.manual-order-entry .row>[class*=col-]{min-width:0}</style><script>
(()=>{const form=document.getElementById('manual-order-form'),search=document.getElementById('manual-product-search'),results=document.getElementById('manual-product-results'),lines=document.getElementById('manual-order-lines'),button=document.getElementById('manual-create'),status=document.getElementById('manual-state');const items=new Map();let timer,abort,seq=0;
const money=n=>'৳'+Number(n).toLocaleString('en-BD',{minimumFractionDigits:2,maximumFractionDigits:2});
function el(tag,text,cls){const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e;}
function update(){let units=0,total=0;for(const x of items.values()){units+=Number(x.qty);total+=x.stock.price*x.qty;}let fee=units>1?units*100:(form.city.value==='In Dhaka City'?100:form.city.value?150:0);document.getElementById('manual-shipping').textContent=form.city.value?money(fee):'Select area';document.getElementById('manual-total').textContent=money(total+fee);button.disabled=!items.size||!form.city.value;}
function render(){lines.replaceChildren();let i=0;for(const [id,x]of items){const row=el('div',null,'manual-order-line mb-3');row.style.gap='10px';const img=el('img');img.src=x.product.image;img.width=42;img.height=56;img.style.objectFit='cover';const detail=el('div');detail.style.minWidth='0';detail.append(el('strong',x.product.name),el('small','Size '+x.stock.size+' · '+money(x.stock.price),'d-block'));const hidden=el('input');hidden.type='hidden';hidden.name=`items[${i}][stock_id]`;hidden.value=id;const qty=el('input',null,'form-control');qty.type='number';qty.min='1';qty.max=String(Math.min(99,x.stock.available));qty.value=x.qty;qty.required=true;qty.name=`items[${i}][quantity]`;qty.style.width='75px';qty.addEventListener('input',()=>{x.qty=Number(qty.value);update();});const remove=el('button','×','btn btn-light');remove.type='button';remove.setAttribute('aria-label','Remove '+x.product.name);remove.onclick=()=>{items.delete(id);render();};row.append(img,detail,hidden,qty,remove);lines.append(row);i++;}update();}
async function load(){const version=++seq;if(abort)abort.abort();abort=new AbortController();results.textContent='Searching…';try{const r=await fetch(@json(route('admin-order-entry.products'))+'?q='+encodeURIComponent(search.value),{headers:{Accept:'application/json'},signal:abort.signal});if(!r.ok)throw Error('Search failed; refresh and retry.');const j=await r.json();if(version!==seq)return;results.replaceChildren();for(const p of j.products){const row=el('div',null,'p-2 border-bottom');const title=el('strong',p.name,'d-block mb-2'),sizes=el('select',null,'form-control form-control-sm');for(const s of p.stocks){const o=el('option',s.size+' · '+money(s.price)+(s.available?'':' · Unavailable'));o.value=s.id;o.disabled=s.available<1;sizes.append(o);}const add=el('button','Add','btn btn-light btn-sm mt-2');add.type='button';add.disabled=!p.stocks.some(s=>s.available>0);add.onclick=()=>{const s=p.stocks.find(s=>String(s.id)===sizes.value);if(!s||s.available<1)return;const current=items.get(s.id);if(current){current.qty=Math.min(current.qty+1,s.available,99);}else if(items.size<20)items.set(s.id,{product:p,stock:s,qty:1});render();};row.append(title,sizes,add);results.append(row);}if(!j.products.length)results.textContent='No products found.';}catch(e){if(e.name!=='AbortError')results.textContent=e.message;}}
search.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(load,350);});form.city.addEventListener('change',update);form.addEventListener('submit',e=>{if(!items.size){e.preventDefault();return;}button.disabled=true;status.textContent='Creating order…';});load();})();
</script>
